import { test, expect } from '@playwright/test';

test.describe('Async Login Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display spinner while login request is in progress', async ({ page }) => {
    // Setup: intercept the login API call
    await page.route('**/api/auth/login', (route) => {
      route.abort('Request aborted');
    });

    // Verify spinner is visible
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Verify login button is disabled
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeDisabled();

    // Verify spinner is visible and has loading text
    const spinnerText = page.getByText(/loading/i);
    await expect(spinnerText).toBeVisible();

    // Verify error message is not visible
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify login form is not empty
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toHaveValue('user@example.com');

    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toHaveValue('password123');

    // Verify login button is still disabled
    await expect(loginButton).toBeDisabled();
  });

  test('should hide spinner and show success message after successful login', async ({ page }) => {
    // Setup: intercept the login API call with success response
    await page.route('**/api/auth/login', (route) => {
      route.continue();
    });

    // Verify spinner is visible
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).toBeVisible();

    // Verify login button is disabled
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await expect(loginButton).toBeDisabled();

    // Verify spinner is visible and has loading text
    const spinnerText = page.getByText(/loading/i);
    await expect(spinnerText).toBeVisible();

    // Verify error message is not visible
    const errorMessage = page.getByText(/error/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify login form is not empty
    const emailInput = page.getByLabel(/email/i);
    await expect(emailInput).toHaveValue('user@example.com');

    const passwordInput = page.getByLabel(/password/i);
    await expect(passwordInput).toHaveValue('password123');

    // Verify login button is still disabled
    await expect(loginButton).toBeDisabled();

    // Click login button
    const loginButton = page.getByRole('button', { name: /sign in/i });
    await loginButton.click();

    // Wait for spinner to disappear
    await page.waitForTimeout(500);

    // Verify spinner is no longer visible
    const spinner = page.getByRole('status', { name: /loading/i });
    await expect(spinner).not.toBeVisible();

    // Verify success message is visible
    const successMessage = page.getByText(/logged in/i);
    await expect(successMessage).toBeVisible();

    // Verify user is redirected to dashboard
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).toBeVisible();

    // Verify user is logged in
    const userName = page.getByText(/user@example.com/i);
    await expect(userName).toBeVisible();
  });
});
